    for (let i = 0; i < 34; i++) { let x = r() * W, y = 18 + r() * (H - 18); for (let k = 0; k < 14; k++) { x += (r() - 0.5) * 8; y += (r() - 0.5) * 5; px(x - 1, y, 3, 1, '#ff8a1f'); px(x, y, 1, 1, '#ffd23f'); } }
    px(0, 18, 8, H, '#ff6a1f'); px(W - 8, 18, 8, H, '#ff6a1f'); px(0, 18, 4, H, '#ffd23f'); px(W - 4, 18, 4, H, '#ffd23f');
