        if (v === 3 || v === 4) { ellipse(gx, 10, 18, 5, v === 3 ? '#4a4a5a' : '#2a1640'); ellipse(gx - 6, 8, 10, 4, v === 3 ? '#5a5a6e' : '#3a1e56'); } // storm cloud / eclipse
